import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Нужно узнать, насколько велика картинка на самом деле, в пикселях, прежде чем загружать её, печатать или передавать клиенту. Имя файла не скажет этого, а миниатюра врёт.</p>\n<p>В этом руководстве мы покажем, как проверить размеры изображения за пять шагов — для одной картинки или целого пакета. Это займёт около минуты, а в итоге у вас будет отчёт, которым можно поделиться.</p>\n<p>Не нужно устанавливать программы, создавать аккаунт или что-либо загружать. Картинки читаются локально в браузере от начала до конца.</p>\n<h2 id=\"what-you-need\">Что нужно перед началом</h2>\n<p>Нужны сами файлы изображений на компьютере или телефоне. Подходят JPG, PNG, WebP, GIF, BMP, HEIC и SVG до 20 МБ каждый.</p>\n<p>Если у вас есть требование платформы, запишите его заранее. Минимальная ширина, требуемое соотношение или целевой размер для печати дают проверке стандарт «прошёл — не прошёл» вместо смутного ощущения.</p>\n<p>Браузер — всё программное обеспечение, которое нужно. Chrome, Safari, Firefox и Edge запускают инструмент на компьютере и телефоне без расширений.</p>\n<p>Для пакетной проверки соберите файлы в одну папку перед началом. Перетащить папку быстрее, чем искать файлы по одному, пока таблица наполовину построена.</p>\n<h2 id=\"step-1-upload-a-batch\">Шаг 1: загрузите одну картинку или целый пакет</h2>\n<p>Откройте <a href=\"/ru/proverit-razmery-izobrazheniya/\">проверку размеров изображения</a> и перетащите файлы в область загрузки. Можно перетащить одну картинку или целую папку сразу.</p>\n<p>Можно также кликнуть по области загрузки, чтобы выбрать файлы, или вставить изображение из буфера обмена через Ctrl+V, чтобы проверить только что сделанный скриншот.</p>\n<p>Таблица начинает заполняться по мере чтения каждого файла. Каждая строка показывает имя файла, размеры в пикселях, соотношение сторон, мегапиксели, размер файла и статус прозрачности.</p>\n<p>Если позже нужно добавить ещё файлы, перетащите их, и они присоединятся к существующей таблице. Инструмент добавляет новые строки, а не стирает те, что уже есть.</p>\n<h2 id=\"step-2-read-the-table\">Шаг 2: прочитайте таблицу размеров</h2>\n<p>Начните со столбца размеров. Он показывает ширину на высоту в пикселях, например 1920 на 1080, и эта пара — самое важное число во всём отчёте.</p>\n<p>Сравните ширину и высоту со своим требованием. Если платформа хочет минимум 1000 пикселей в ширину, а картинка — 800, она не проходит, как бы хорошо ни выглядела.</p>\n<p>Затем взгляните на столбец мегапикселей. Он с первого взгляда показывает общее число пикселей — полезно, когда сравниваешь две картинки разной формы, но похожего размера.</p>\n<p>Наконец, проверьте столбец размера файла. Очень маленький файл с большими размерами может быть сильно сжат — это тревожный знак для печати, даже если пиксели в порядке.</p>\n<h2 id=\"step-3-check-the-ratio\">Шаг 3: проверьте соотношение сторон</h2>\n<p>Столбец соотношения показывает форму каждой картинки, например 16:9, 4:3 или 1:1. Он также показывает точное соотношение, когда картинка не совпадает со стандартной формой.</p>\n<p>Сопоставьте соотношение с местом назначения. Портрет 4:5 лучше заполняет ленту телефона, чем квадрат, а альбомный 16:9 подходит для превью видео или главного баннера сайта.</p>\n<p>Следите за почти-попаданиями. Картинка 1,48:1 выглядит почти квадратной, но это не 3:2, и платформа, которая обрезает до 3:2, обрежет её края так, как вы не планировали.</p>\n<p>Если соотношение неверное, сначала обрежьте картинку. <a href=\"/ru/obrezat-izobrazhenie/\">Инструмент обрезки изображений</a> режет точно до нужного соотношения, а проверка после этого подтверждает результат.</p>\n<h2 id=\"step-4-validate-minimums\">Шаг 4: проверьте минимальную ширину и высоту</h2>\n<p>Введите минимумы вашей платформы в поля «Минимальная ширина» и «Минимальная высота». Инструмент пометит каждую картинку, которая ниже любого из чисел.</p>\n<p>Помеченные строки — ваш список задач. Каждой нужен либо более крупный исходник, либо изменение размера, либо решение принять более низкое качество.</p>\n<p>Не увеличивайте помеченную картинку и не считайте проблему решённой. Увеличение придумывает пиксели, поэтому файл проходит числовую проверку, выглядя мягче настоящего изображения в высоком разрешении.</p>\n<p>Когда исходник нельзя сделать больше, поговорите с тем, кто его предоставил. Фотограф или дизайнер с оригиналом обычно может экспортировать версию побольше за секунды.</p>\n<h2 id=\"step-5-export-the-report\">Шаг 5: экспортируйте отчёт в CSV или JSON</h2>\n<p>Когда таблица готова, нажмите «Экспорт CSV» для таблицы или «Экспорт JSON» для структурированного файла данных. Оба содержат те же столбцы, что и таблица на экране.</p>\n<p>CSV открывается в Excel или Google Таблицах, где можно сортировать по ширине, фильтровать по соотношению или выделять помеченные строки, чтобы коллега их исправил.</p>\n<p>JSON — для разработчиков и автоматизированных конвейеров. Он несёт те же данные в формате, который может прочитать скрипт, что подходит контентным системам и панелям качества.</p>\n<p>Экспортируйте до закрытия вкладки, потому что таблица живёт только в браузере. Обновление страницы стирает её, а повторная проверка большого пакета — потеря времени.</p>\n<h2 id=\"checking-one-image\">Как быстро проверить одну картинку</h2>\n<p>Для одной картинки процесс тот же, но быстрее. Перетащите файл, прочитайте строку размеров — и готово меньше чем за десять секунд.</p>\n<p>Вставка — самый быстрый путь для скриншотов. Скопируйте скриншот, нажмите Ctrl+V в инструменте, и размеры появятся без сохранения файла.</p>\n<p>На телефоне загрузите картинку из галереи. Таблица работает на маленьких экранах, а ключевые числа видны без прокрутки вбок.</p>\n<p>Проверка одной картинки — также самый быстрый способ разрешить спор. Когда двое не сходятся в том, достаточно ли велика картинка, проверка даёт число, с которым не поспоришь.</p>\n<h2 id=\"reading-the-print-size\">Как читать столбец размера для печати</h2>\n<p>Столбец «Печать при 300 DPI» переводит пиксели в дюймы при качестве печати. Картинка шириной 3000 пикселей показывается как 10 дюймов — это её безопасная печатная ширина.</p>\n<p>Сравните это число с размером, который нужен на самом деле. Если нужен отпечаток 8 дюймов, а в столбце — 4 дюйма, картинка будет выглядеть мягкой при растяжении.</p>\n<p>Помните, что 300 DPI — это стандарт качества, а не закон. Постер, который смотрят с расстояния через комнату, можно напечатать при 150 DPI, а брошюру, которую держат в руках, нужно печатать при полных 300.</p>\n<p>По общим вопросам печати <a href=\"/ru/izmenit-dpi-izobrazheniya/\">инструмент изменения DPI изображения</a> может задать метаданные DPI ваших файлов, когда вы знаете, что пикселей достаточно.</p>\n<h2 id=\"spotting-misleading-extensions\">Как распознать вводящие в заблуждение расширения</h2>\n<p>Файл с именем .jpg не всегда является JPEG. Люди переименовывают файлы, а некоторые системы по ошибке сохраняют WebP с расширением .jpg.</p>\n<p>Проверка читает настоящие данные картинки, а не расширение. Если предполагаемый JPG окажется WebP, инструмент сообщит, чем файл является на самом деле.</p>\n<p>Это важно, потому что некоторые платформы отклоняют файлы, содержимое которых не совпадает с расширением. Поймать несоответствие в проверке — значит избежать неудачной загрузки позже.</p>\n<p>Если нашли неверно названный файл, конвертируйте его правильно, а не переименовывайте снова. <a href=\"/ru/konvertirovat-izobrazhenie/\">Конвертер изображений</a> записывает правильный файл с верным форматом и расширением.</p>\n<h2 id=\"checking-svg-files\">Проверка файлов SVG</h2>\n<p>Файлы SVG — это векторы, поэтому проверка читает их собственные размеры из атрибутов ширины, высоты и viewBox, а не считает пиксели.</p>\n<p>Собственный размер — это размер, который задумал дизайнер. SVG можно масштабировать намного дальше без потери резкости, но задуманный размер говорит, какие пропорции сохранять.</p>\n<p>Если у SVG есть viewBox, но нет ширины и высоты, проверка показывает соотношение без абсолютных размеров. Это нормально для отзывчивых иконок, созданных для масштабирования.</p>\n<p>Для иконок сравните соотношение SVG с вашим макетом. viewBox 0 0 24 24 — квадратный, и размещение его в широком слоте либо растянет его, либо оставит пустое место.</p>\n<h2 id=\"troubleshooting-unreadable-files\">Что делать с нечитаемыми файлами</h2>\n<p>Иногда файл вообще не читается, и инструмент помечает его как ошибку. Обычная причина — повреждённая загрузка или файл, который на самом деле не является картинкой.</p>\n<p>Сначала попробуйте открыть файл в просмотрщике изображений. Если просмотрщик тоже не справляется, файл повреждён, и его нужно скачать заново или экспортировать из источника.</p>\n<p>Файл больше 20 МБ также будет отклонён. Сначала сожмите его или измените размер, а затем проверьте меньшую версию — ведь именно её размеры вы будете использовать.</p>\n<p>Один плохой файл никогда не блокирует остальной пакет. Проверка сообщает о строке с ошибкой и продолжает читать остальные файлы, поэтому сломанный можно исправить потом.</p>\n<h2 id=\"fixing-a-failed-image\">Как исправить картинку, не прошедшую проверку</h2>\n<p>Начните с источника. Попросите оригинальный экспорт в большем размере, прежде чем пробовать программные исправления, ведь настоящий файл в высоком разрешении лучше любой увеличенной копии.</p>\n<p>Если неверно соотношение, обрежьте картинку. Инструмент обрезки режет точно до соотношения, которое хочет платформа, а свежая проверка подтверждает новые размеры.</p>\n<p>Если файл слишком мал и более крупного источника нет, измените его размер с помощью <a href=\"/ru/izmenit-razmer-izobrazheniya/\">инструмента изменения размера изображений</a> и примите мягкость. Это лучше, чем не пройти загрузку, но честно скажите клиенту о качестве.</p>\n<p>Проверяйте заново после каждого исправления. Второй проход через проверку подтверждает новые размеры и даёт чистый отчёт для готовой работы.</p>\n<h2 id=\"sharing-the-report\">Как поделиться отчётом с командой</h2>\n<p>Отчёт в CSV — самое простое, чем можно поделиться. Отправьте его дизайнеру, разработчику или клиенту, и все увидят одни и те же числа вместо споров по памяти.</p>\n<p>Выделите помеченные строки перед отправкой. Отчёт с чётко отмеченными сбоями исправляется быстрее, чем сырая таблица, в которой читатель должен искать проблемы.</p>\n<p>Для повторяющейся работы договоритесь о минимальном размере один раз и запишите его. Каждый будущий пакет будет проверяться по тому же стандарту, а отчёты станут сравнимыми со временем.</p>\n<p>Храните старые отчёты в папке проекта. Когда платформа меняет требования, старый отчёт показывает, какие картинки раньше соответствовали, а какие нужно перепроверить сейчас.</p>\n<h2 id=\"checking-before-print\">Проверка размеров перед заказом печати</h2>\n<p>Заказы печати — самое дорогое место для обнаружения проблемы с размерами, ведь ошибка видна только после того, как работа напечатана и оплачена. Двухминутная проверка заранее — самая дешёвая страховка во всём процессе.</p>\n<p>Начните с того, что спросите у типографии готовый размер в дюймах и DPI, который они хотят, — обычно 300. Умножьте дюймы на DPI, чтобы получить нужные размеры в пикселях, и запишите это число.</p>\n<p>Прогоните картинки через проверку и сравните каждую с этим целевым значением. Любая картинка, которая не дотягивает, напечатается мягко, а нехватка точно покажет, насколько меньше должен быть отпечаток, чтобы остаться резким.</p>\n<p>Обратите внимание и на соотношение, а не только на размер. Типография, которая обрезает до фиксированного соотношения, обрежет вашу картинку, поэтому убедитесь, что важные детали безопасно лежат внутри области обрезки.</p>\n<p>Заодно проверьте формат файла. Типографии предпочитают JPG или TIFF для фотографий и PDF или PNG для графики, а файл в неверном формате может вызвать задержки, даже когда размеры правильные.</p>\n<p>Наконец, экспортируйте отчёт и отправьте его типографии вместе с файлами. Типография, которая видит таблицу размеров, заметит проблему до запуска станка — это куда лучше, чем заметить её на готовых листах.</p>\n<h2 id=\"recurring-batch-checks\">Как сделать проверку размеров привычкой</h2>\n<p>Разовые проверки ловят разовые проблемы, но большинство сбоев размеров повторяются. Тот же поставщик каждый месяц присылает маленькие картинки, или тот же шаблон снова экспортирует с неверным соотношением.</p>\n<p>Встройте проверку в рабочий процесс вместо того, чтобы относиться к ней как к экстренному шагу. Прогоняйте каждый новый пакет картинок через проверку в момент его получения, прежде чем кто-то начнёт с ним проектировать.</p>\n<p>Ведите простой журнал того, что не прошло и почему. Через несколько недель закономерность станет очевидной, и можно будет исправить источник — неверный пресет экспорта, небрежного поставщика или шаблон, который нужно обновить, — вместо того чтобы исправлять каждую картинку вручную.</p>\n<p>Поделитесь привычкой с командой. Когда все проверяют размеры перед передачей файлов, сбои перестают приходить в последний момент, и проверка становится тихим фоновым шагом, а не спасательным инструментом.</p>\n<h2 id=\"quick-reference-checklist\">Быстрая шпаргалка</h2>\n<p>Перетащите файлы, сначала прочитайте столбец размеров, затем соотношение, затем мегапиксели и размер файла для контекста.</p>\n<p>Введите минимальную ширину и высоту, пометьте сбои и исправляйте их по возможности из исходного файла, а не увеличением.</p>\n<p>Проверьте столбец размера для печати перед отправкой чего-либо в печать и экспортируйте отчёт в CSV или JSON до закрытия вкладки.</p>\n<p>Вот пример из практики. Типография просит фото для буклета размером 15 на 21 сантиметр при 300 DPI. Вы умножаете сантиметры на DPI, получаете нужные пиксели и прогоняете файлы через проверку. Те, что не дотягивают, сразу видны в таблице — их нужно заменить, а не надеяться на удачу.</p>\n<p>Скриншоты с телефона тоже стоит проверять. Современные телефоны делают снимки экрана в высоком разрешении, но после отправки через мессенджер картинка может сжаться в несколько раз. Проверка покажет реальные пиксели того файла, который у вас на руках, а не того, что был на экране.</p>\n<p>Если вы готовите изображения для сайта, проверяйте их до загрузки в CMS. Многие системы автоматически сжимают картинки, и узнать их исходные размеры после загрузки уже сложнее. Минута проверки заранее экономит часы переделок потом.</p>\n<p>Храните отчёты по проектам в отдельных папках. Когда клиент через полгода попросит «те же картинки, но для печати», вы откроете старый CSV и сразу увидите, какие файлы подойдут, а какие нужно переснять.</p>\n<p>Проверяйте размеры и у картинок, которые прислали коллеги. Файл с именем final-v2 может оказаться уменьшенной копией для письма, а не оригиналом для печати. Одна проверка спасает от ошибки, которая всплыла бы только в типографии.</p>\n<p>И последний совет: проверяйте размеры сразу, как только получили файлы, а не перед самой загрузкой. Когда проблема находится за пять минут до дедлайна, её уже не исправить — а когда она найдена в день получения файлов, у фотографа или дизайнера есть время прислать правильную версию.</p>\n<p>Полный контекст — в статье <a href=\"/ru/blog/kak-uznat-razmer-izobrazheniya-v-pikselyah/\">Как узнать размер изображения в пикселях: полное руководство</a>, а теорию чисел смотрите в статье <a href=\"/ru/blog/razmer-razreshenie-i-ves-izobrazheniya-chem-otlichayutsya/\">Размер, разрешение и вес изображения: чем отличаются</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Как проверить размеры картинки на телефоне?","answer":"Откройте проверку размеров в мобильном браузере и загрузите картинку из галереи. Таблица показывает ширину, высоту, соотношение и мегапиксели. Можно также вставить скриншот напрямую, чтобы проверить его размер в пикселях без сохранения файла."},{"question":"Можно ли проверить размеры без скачивания программ?","answer":"Да. Проверка полностью работает в браузере на компьютере и телефоне. Нечего устанавливать, не нужно создавать аккаунт, а ваши файлы никогда не загружаются на сервер."},{"question":"Почему Windows показывает один размер моей картинки, а проверка — другой?","answer":"Проводник Windows иногда показывает размеры округлёнными или масштабированными для отображения, а некоторые программы показывают размер после применения настроек DPI. Проверка читает истинную ширину и высоту в пикселях, записанные внутри файла, а именно это число проверяют платформы."},{"question":"Какая минимальная ширина хороша для фото товаров?","answer":"Зависит от платформы, но большинство маркетплейсов хотят минимум 1000 пикселей по длинной стороне, чтобы покупатели могли увеличивать картинку. Всегда проверяйте актуальные правила конкретного маркетплейса, а затем введите это число в поле проверки минимальной ширины."},{"question":"Может ли проверка прочитать размеры со вставленного скриншота?","answer":"Да. Скопируйте скриншот и нажмите Ctrl+V в инструменте, и он сразу прочитает размеры в пикселях. Это самый быстрый способ проверить размер снимка экрана перед отправкой кому-то."},{"question":"Что делать, если моя картинка меньше требуемого размера?","answer":"Сначала попросите исходный файл в большем размере, ведь увеличение придумывает пиксели и смягчает картинку. Если большего источника нет, измените размер с помощью инструмента изменения размера и примите компромисс в качестве, а затем проверьте заново, чтобы подтвердить новые размеры."}];
